def candidates(grid,k):
    found=[]
    h,w=len(grid),len(grid[0])
    for r in range(h-k+1):
      for c in range(w-k+1):
        col=grid[r][c]
        if all(grid[i][j]==col for i in range(r,r+k) for j in range(c,c+k)):
          found.append((r,c,col))
    return found
